command:
// ==========================================
// LUNAS WIRKUNG: GETEILTES LEID (RONDRA)
//
// - mehrere Targets ohne Reichweitenprüfung
// - Zielkategorie: Zweibeiner, Tiere, Erwachte
// - zentrale Zweibeiner-Erkennung über Block 2
// - erstes gültiges Ziel wird verbunden
// - ungültige Ziele bleiben Misserfolg
// - gekoppelte sichtbare Effekte über Block 6
// - gemeinsames Wirkungsende über Block 7
// - Trefferwächter zentral über Block 12
// - Schadenskarte zentral über Block 12
// - parallele Reaktion mit anderen Gaben
// - eine Karte + roter GM-Button über Block 11
// ==========================================

(async function () {
const macroUuid = this?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.Wesen?.match || !globalThis.DSK?.Wesen?.IstZweibeiner ||
    !globalThis.DSK?.Schaden?.GMKarte || !globalThis.DSK?.Schaden?.IstAktiverGM ||
    !globalThis.DSK?.Schaden?.Angriffswaechter?.Register || !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Target?.Merken ||
    !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.Wesen?.match || !DSK_FW?.Wesen?.IstZweibeiner ||
    !DSK_FW?.Schaden?.GMKarte || !DSK_FW?.Schaden?.IstAktiverGM ||
    !DSK_FW?.Schaden?.Angriffswaechter?.Register || !DSK_FW?.QS?.Ermitteln ||
    !DSK_FW?.Token?.Finde || !DSK_FW?.Target?.Merken ||
    !DSK_FW?.Target?.Finden || !DSK_FW?.Target?.Actor ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton || !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.03 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Geteiltes Leid", vollerName = "Geteiltes Leid (Rondra)", ahne = "Rondra";
const reaktionsKey = "geteiltesLeidRondra", flagKey = "pendingGeteiltesLeidRondra";
const endeText = "Das Band des geteilten Leids zerreißt. Beide Wesen tragen ihr Leid wieder allein.";

globalThis._dskGeteiltesLeidUnterdrueckt ||= new Set();
DSK_FW.EffektEnde.Register(reaktionsKey, vollerName, endeText);

// +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const effektSchluessel = effect => effect?.uuid || `${effect?.parent?.uuid || "Actor"}.${effect?.id || "Unbekannt"}`;

const ladeActor = async uuid => {
    if (!uuid) return null;
    try {
        const doc = await fromUuid(uuid);
        return doc?.documentName === "Token" ? doc.actor : doc || null;
    } catch (error) {
        console.warn("Geteiltes Leid: Akteur konnte nicht geladen werden.", { uuid, error });
        return null;
    }
};

const ladeGespeichertesZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const istGueltigesZiel = actor =>
    Boolean(actor) && (
        DSK_FW.Effekt.CheckTarget(actor, "erwachte") ||
        DSK_FW.Wesen.match(actor, ["tier", "tiere", "animal"]) ||
        DSK_FW.Wesen.IstZweibeiner(actor)
    );

const findeVerbindungsEffekt = (actor, verbindungsId) => actor?.effects?.find(effect =>
    !effect.disabled &&
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "schadensReaktion") === reaktionsKey &&
    effect.getFlag("dsk", "verbindungsId") === verbindungsId
) || null;

const findeAlteEffekte = actor => (actor?.effects || []).filter(effect =>
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "schadensReaktion") === reaktionsKey
);

const loescheOhnePartnerReaktion = async effect => {
    if (!effect) return false;
    const key = effektSchluessel(effect);
    globalThis._dskGeteiltesLeidUnterdrueckt.add(key);
    try { await effect.delete(); return true; }
    finally { setTimeout(() => globalThis._dskGeteiltesLeidUnterdrueckt.delete(key), 500); }
};

// +++ 4 - PARTNEREFFEKTE GEMEINSAM BEENDEN +++++++++++++++++++

if (globalThis._dskGeteiltesLeidDeleteHook) Hooks.off("preDeleteActiveEffect", globalThis._dskGeteiltesLeidDeleteHook);

globalThis._dskGeteiltesLeidDeleteHook = Hooks.on("preDeleteActiveEffect", async effect => {
    if (!effect || !DSK_FW.Schaden.IstAktiverGM()) return;
    if (globalThis._dskGeteiltesLeidUnterdrueckt.has(effektSchluessel(effect))) return;

    const flags = effect.flags?.dsk || {};
    if (flags.schadensReaktion !== reaktionsKey || !flags.verbindungsId || !flags.partnerUuid) return;

    const partnerActor = await ladeActor(flags.partnerUuid);
    const partnerEffekt = findeVerbindungsEffekt(partnerActor, flags.verbindungsId);
    if (partnerEffekt) await loescheOhnePartnerReaktion(partnerEffekt);
});

// +++ 5 - REAKTIONSWÄCHTER ÜBER BLOCK 12 +++++++++++++++++++++

const registriereReaktion = ({ actor, effect, verbindungsId, rolle }) => {
    if (!actor || !effect || !verbindungsId) return null;

    return DSK_FW.Schaden.Angriffswaechter.Register({
        key: `${reaktionsKey}-${verbindungsId}-${rolle}`,
        actor, effektId: effect.id, effektUuid: effect.uuid,
        rolle: "verteidiger", einmalig: false, protokollieren: true,

        beiErfolg: async ({ effekt, message, angriff }) => {
            if (!DSK_FW.Schaden.IstAktiverGM() || !effekt || !angriff || angriff.schaden <= 0) return false;

            const getroffenActor = effekt.parent;
            const gespeicherteVerbindung = effekt.getFlag("dsk", "verbindungsId");
            const partnerUuid = effekt.getFlag("dsk", "partnerUuid");
            if (!getroffenActor || gespeicherteVerbindung !== verbindungsId || !partnerUuid) return false;

            const partnerActor = await ladeActor(partnerUuid);
            const partnerEffekt = findeVerbindungsEffekt(partnerActor, verbindungsId);

            if (!partnerActor || !partnerEffekt || partnerEffekt.getFlag("dsk", "partnerUuid") !== getroffenActor.uuid) {
                console.warn("Geteiltes Leid: Die gegenseitige Verbindung ist nicht mehr vollständig.", {
                    getroffenActor: getroffenActor?.name, partnerUuid, verbindungsId
                });
                return false;
            }

            const getroffenName = DSK_FW.ResolveTokenName(getroffenActor);
            const partnerName = DSK_FW.ResolveTokenName(partnerActor);

            const schadensKarte = await DSK_FW.Schaden.GMKarte({
                key: `${reaktionsKey}-${message.id}`,
                titel: "Geteiltes Leid – Schadensaufteilung", ahne,
                zusammenfassung: `Getroffen: ${getroffenName}`,
                beschreibung:
                    `<b>${getroffenName}</b> wurde getroffen. Der erkannte Schaden kann durch die Spielleitung angepasst werden. ` +
                    `Anschließend wird die abgerundete Hälfte auf beide verbundenen Wesen verteilt.`,
                modus: "teilen", basis: angriff.schaden, teiler: 2,
                ziele: [
                    { uuid: getroffenActor.uuid, name: getroffenName },
                    { uuid: partnerActor.uuid, name: partnerName }
                ],
                buttonText: "Geteilten Schaden anwenden",
                bestaetigungsTitel: "Geteiltes Leid – Schaden angewendet",
                quelleUuid: getroffenActor.uuid, lepDetailsVerbergen: true
            });

            return Boolean(schadensKarte);
        }
    });
};

// +++ 6 - GEKOPPELTE EFFEKTE ÜBER BLOCK 6 ++++++++++++++++++++

const wendeVerbindungAn = async ({ casterActor, casterName, targetActor, targetName, qs, verbindungsId }) => {
    if (!casterActor || !targetActor) return false;

    const dauerMinuten = qs;
    const beschreibung =
        `<b>${casterName}</b> und <b>${targetName}</b> teilen ihr Leid.` +
        `<br><br>Gewinnt ein Gegner gegen einen der beiden Effektträger, wird der Schaden ` +
        `abgerundet halbiert und auf beide verbundenen Wesen verteilt.` +
        `<br><br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`;

    for (const effect of [...findeAlteEffekte(casterActor), ...findeAlteEffekte(targetActor)]) {
        await loescheOhnePartnerReaktion(effect);
    }

    let casterEffekt = null, targetEffekt = null;

    try {
        casterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: `${beschreibung}<br><br><b>Rolle:</b> Wirkender<br><b>Verbunden mit:</b> ${targetName}`,
            gabeZiel: "", qs, skills: ["flags.dsk.geteiltesLeidAktiv"],
            key: "flags.dsk.geteiltesLeidAktiv", formel: "1", ziel: casterActor,
            duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime }, showIcon: 1,
            flags: { dsk: {
                isGeteiltesLeid: true, geteiltesLeidAktiv: 1,
                casterUuid: casterActor.uuid, casterName, qs,
                schadensReaktion: reaktionsKey, verbindungsId,
                partnerUuid: targetActor.uuid, partnerName: targetName,
                rolle: "wirkender", modus: "teilen", teiler: 2,
                wirkungsende: { sfName: reaktionsKey, basisEffektName: vollerName, beschreibungFuerEnde: endeText }
            }}
        });

        if (!casterEffekt) throw new Error("Der Effekt auf dem Wirkenden konnte nicht erstellt werden.");

        targetEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: `${beschreibung}<br><br><b>Rolle:</b> Verbundenes Ziel<br><b>Verbunden mit:</b> ${casterName}`,
            gabeZiel: "", qs, skills: ["flags.dsk.geteiltesLeidAktiv"],
            key: "flags.dsk.geteiltesLeidAktiv", formel: "1", ziel: targetActor,
            duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime }, showIcon: 1,
            flags: { dsk: {
                isGeteiltesLeid: true, geteiltesLeidAktiv: 1,
                casterUuid: casterActor.uuid, casterName, qs,
                schadensReaktion: reaktionsKey, verbindungsId,
                partnerUuid: casterActor.uuid, partnerName: casterName,
                rolle: "ziel", modus: "teilen", teiler: 2,
                wirkungsende: { sfName: reaktionsKey, basisEffektName: vollerName, beschreibungFuerEnde: endeText }
            }}
        });

        if (!targetEffekt) throw new Error("Der Effekt auf dem verbundenen Ziel konnte nicht erstellt werden.");

        const pruefeEffekt = (effect, partnerUuid, partnerName, rolle) => {
            const endeDaten = effect?.getFlag("dsk", "wirkungsende");
            const korrekterSystemwert = (effect?.changes || []).some(change =>
                change.key === "flags.dsk.geteiltesLeidAktiv" &&
                Number(change.mode) === 2 && Number(change.value) === 1
            );

            return (
                (effect?.name || effect?.label || "") === vollerName &&
                effect.getFlag("dsk", "isGeteiltesLeid") === true &&
                effect.getFlag("dsk", "casterUuid") === casterActor.uuid &&
                effect.getFlag("dsk", "schadensReaktion") === reaktionsKey &&
                effect.getFlag("dsk", "verbindungsId") === verbindungsId &&
                effect.getFlag("dsk", "partnerUuid") === partnerUuid &&
                effect.getFlag("dsk", "partnerName") === partnerName &&
                effect.getFlag("dsk", "rolle") === rolle &&
                effect.getFlag("dsk", "modus") === "teilen" &&
                Number(effect.getFlag("dsk", "teiler")) === 2 &&
                Number(effect.getFlag("dsk", "qs")) === qs &&
                endeDaten?.sfName === reaktionsKey &&
                endeDaten?.basisEffektName === vollerName &&
                endeDaten?.beschreibungFuerEnde === endeText &&
                korrekterSystemwert
            );
        };

        if (
            !pruefeEffekt(casterEffekt, targetActor.uuid, targetName, "wirkender") ||
            !pruefeEffekt(targetEffekt, casterActor.uuid, casterName, "ziel")
        ) throw new Error("Die gegenseitige Verbindung ist unvollständig.");

        const casterWaechter = registriereReaktion({
            actor: casterActor, effect: casterEffekt, verbindungsId, rolle: "wirkender"
        });

        const targetWaechter = registriereReaktion({
            actor: targetActor, effect: targetEffekt, verbindungsId, rolle: "ziel"
        });

        if (!casterWaechter || !targetWaechter) {
            throw new Error("Die beiden Schadensreaktionen konnten nicht vollständig registriert werden.");
        }

        return true;

    } catch (error) {
        console.error("Geteiltes Leid: Effektanlage oder Wächterregistrierung fehlgeschlagen.", {
            casterActor: casterActor.name, targetActor: targetActor.name, verbindungsId, error
        });

        if (targetEffekt) await loescheOhnePartnerReaktion(targetEffekt);
        if (casterEffekt) await loescheOhnePartnerReaktion(casterEffekt);
        return false;
    }
};

// +++ 7 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!casterActor || !daten || !DSK_FW.Schaden.IstAktiverGM()) return false;

    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
        ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
        return false;
    }

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    const { token: targetToken, actor: targetActor } = await ladeGespeichertesZiel(daten.target);
    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const targetName = daten.target?.name || targetToken?.name || targetActor?.name || "Unbekanntes Ziel";
    const misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const fehlschlag = async grund => {
        misserfolge.push({ name: targetName, grund });
        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId, gabenName: vollerName, ahne,
            beschreibung: daten.beschreibung || "", wirkender: casterName,
            ziele: [], misserfolge, dauerText: `${qs} Minuten`, erfolgreich: false
        });
        return true;
    };

    if (!targetActor) return fehlschlag("Ziel wurde nicht gefunden");
    if (!istGueltigesZiel(targetActor)) return fehlschlag("Kein Zweibeiner/Tier/Erwachter");

    const disposition = targetToken?.document?.disposition ?? daten.target?.disposition ?? null;
    if (Number(disposition) === -1) return fehlschlag("Feindliches Ziel");

    const verbindungsId = daten.verbindungsId || `geteiltes-leid-${Date.now()}-${foundry.utils.randomID()}`;
    const erfolgreich = await wendeVerbindungAn({ casterActor, casterName, targetActor, targetName, qs, verbindungsId });

    if (!erfolgreich) {
        misserfolge.push({
            name: targetName,
            grund: "Partnerverbindung oder Schadensreaktion konnte nicht vollständig hergestellt werden"
        });
    }

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId, gabenName: vollerName, ahne,
        beschreibung: daten.beschreibung || "", wirkender: casterName,
        ziele: erfolgreich ? [{ name: targetName, rolle: "Ziel" }] : [],
        misserfolge, dauerText: `${qs} Minuten`, erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: ${casterName} und ${targetName} teilen nun ihr Leid.`);
    else ui.notifications.error("Luna sagt 🌙: Die Verbindung konnte nicht vollständig hergestellt werden!");

    return true;
};

// +++ 8 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;
            if (await verarbeiteAnfrage(anfrageActor, daten)) await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
        }
        return;
    }
}

// +++ 9 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Geteiltes Leid Probe", "Geteiltes Leid"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Das Band des geteilten Leids konnte nicht geknüpft werden.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName, grund: "Probe fehlgeschlagen" }],
        dauerText: "0 Minuten", gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

// +++ 10 - TARGETS PRÜFEN +++++++++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);
if (!targets.length) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");
}

const gueltigeZiele = [], misserfolge = [];

for (const targetToken of targets) {
    const targetActor = targetToken?.actor;
    const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Target";

    if (!targetActor) {
        misserfolge.push({ name: targetName, grund: "Kein gültiger Akteur" });
        continue;
    }

    if (targetActor.uuid === casterActor.uuid || targetActor.id === casterActor.id) {
        misserfolge.push({ name: targetName, grund: "Wirkender kann nicht sein eigenes Ziel sein" });
        continue;
    }

    if (!istGueltigesZiel(targetActor)) {
        misserfolge.push({ name: targetName, grund: "Kein Zweibeiner/Tier/Erwachter" });
        continue;
    }

    if (Number(targetToken.document?.disposition) === -1) {
        misserfolge.push({ name: targetName, grund: "Feindliches Ziel" });
        continue;
    }

    const zielDaten = DSK_FW.Target.Merken(targetToken);
    if (!zielDaten) {
        misserfolge.push({ name: targetName, grund: "Ziel konnte nicht gespeichert werden" });
        continue;
    }

    gueltigeZiele.push({ ...zielDaten, disposition: targetToken.document?.disposition ?? null });
}

const beschreibung =
    `Gewinnt ein Gegner gegen einen der beiden Effektträger, wird der Schaden ` +
    `abgerundet halbiert und auf beide verbundenen Wesen verteilt.` +
    `<br><br><b>Zielkategorie:</b> Zweibeiner, Tiere, Erwachte`;

if (!gueltigeZiele.length) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [], misserfolge, dauerText: `${qs} Minuten`,
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

const targetDaten = gueltigeZiele[0], targetName = targetDaten.name || "Unbekanntes Ziel";
const verbindungsId = `geteiltes-leid-${Date.now()}-${foundry.utils.randomID()}`;

for (const weiteresZiel of gueltigeZiele.slice(1)) {
    misserfolge.push({ name: weiteresZiel.name || "Weiteres Ziel", grund: "Geteiltes Leid verbindet genau ein Ziel" });
}

// +++ 11 - GEMEINSAME KARTE + ANFRAGE +++++++++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: [{ name: targetName, rolle: "Ziel" }], misserfolge,
    dauerText: `${qs} Minuten`, gmLink, gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
